# Implied true full cost from the relationship charge in each relationship-goal deal
import json,glob,math
from arena_kit.cost import closing_terms, _years, _soft
def implied(case, terms, rel):
    b=case["buyer"]; per=b.get("relationship_eur_per_point"); sust=b.get("sustainable_margin_pct")
    if not per or not sust: return None
    t=closing_terms(case, terms); years=_years(case,t)
    target=rel/(per*years)
    # invert soft: gap in points
    if target<=0: return ("<=", round(t["unit_price"]*(1-sust/100),2))
    gap = math.sqrt(10*target) if target<=2.5 else target+2.5
    margin=sust-gap
    # margin = (worth - fc)/worth ; worth≈ supplier_value ~ price at its standard payment; approximate worth by price
    return ("=", round(t["unit_price"]*(1-margin/100),2), "gap",round(gap,2))
seen={}
for p in sorted(glob.glob("logs/sessions/practice/*.json")):
    d=json.load(open(p)); r=d.get("result") or {}
    case=d.get("case") or {}
    if not case:
        continue
    if not r.get("deal") or case["buyer"].get("category_goal") not in ("stabilise","secure_supply"): continue
    cb=r["cost_breakdown"]; rel=sum(v.get("relationship",0) for v in cb.values()) if isinstance(next(iter(cb.values())),dict) else cb.get("relationship")
    t=r["terms"]
    print(d["case_id"], d["session_id"][:8], round(r["score"],3), t["unit_price"], t.get("payment_days"), "clause" if t.get("index_clause") else "", "rel",round(rel), implied(case,t,rel), "c_best",r["c_best"])
EOF

